export function renderCurveDomainControl(editor,bar){const d=editor.track?.infinityDomain;if(!d)return;const button=editor.document.createElement('button');button.type='button';button.dataset.curveDomainClear='';button.textContent='주기 '+d.start+'–'+d.end+'초';button.title='원래 주기 고정 해제';button.onclick=()=>{if(editor.change(candidate=>{delete candidate.tracks.find(t=>t.id===editor.trackId).infinityDomain;}))editor.render();};bar.append(button);}
